function openTool(id){const t=tools.find(x=>x.id===id);if(!t)return;if(['calendar','vault','checklist'].includes(id)){switchView(id);return}activeTool=id;latestOutput='';$('#modalIcon').textContent=t.icon;$('#modalIcon').style.setProperty('--icon-color',t.color);$('#modalIcon').style.color=t.color;$('#modalIcon').style.background=t.bg;$('#modalCategory').textContent=t.category.toUpperCase();$('#modalTitle').textContent=t.name;$('#saveToolOutput').textContent='♡ Save output';$('#toolModal').classList.add('open');$('#toolModal').setAttribute('aria-hidden','false');lastFocus=document.activeElement;const body=$('#modalBody');body.innerHTML=toolContent(id);bindTool(id);setTimeout(()=>body.querySelector('input:not([type=range]),textarea,select,button')?.focus(),60)}
